#!/usr/bin/env bash
set -euo pipefail

ROOT="$(cd "$(dirname "${BASH_SOURCE[0]}")/../.." && pwd)"
PROFILE="$ROOT/build/titan2/n1d-c3b-e2-product-admission.env"
ADAPTER="$ROOT/build/titan2/stage-c3b-product-review.sh"
STAGING_GATE="$ROOT/build/gates/n1d-c3b-product-review-staging-contract.sh"
TRANSITION="$ROOT/build/titan2/n1d-c3b-transition.env"

fail() {
    echo "N1D_C3B_E2_PRODUCT_ADMISSION_CONTRACT=FAIL $*" >&2
    exit 1
}

for f in "$PROFILE" "$ADAPTER" "$STAGING_GATE" "$TRANSITION"; do
    [[ -f "$f" ]] || fail "missing_file=$f"
done

bash -n "$PROFILE" || fail "syntax=$PROFILE"
bash -n "$ADAPTER" || fail "syntax=$ADAPTER"
bash "$STAGING_GATE"

require_line() {
    local line="$1"
    grep -Fxq "$line" "$PROFILE" || fail "missing_line=$line"
}

for line in     'N1D_C3B_E2_ADMISSION_VERSION=1'     'N1D_C3B_E2_ADMISSION_DATE=2026-10-02'     'N1D_C3B_E2_PHASE=C3B_E2_PRODUCT_SOURCE_ADMISSION'     'N1D_C3B_E2_E1_PR=234'     'N1D_C3B_E2_E1_MERGE_COMMIT=39b0733817fa8482fe168277fb0cd119cdc7ae1a'     'N1D_C3B_E2_E1_SYSTEM_SHA256=9ce0144220b3a5bf531a1b0da7ec97543a89c9181ab9d69b6390ea5a86ad45dd'     'N1D_C3B_E2_E1_SYSTEM_BYTES=2940891136'     'N1D_C3B_E2_E1_PREREQUISITE=PASS_SYSTEMIMAGE'     'N1D_C3B_E2_PRODUCT_SOURCE_REPO=aimindseye/titan2-temp'     'N1D_C3B_E2_PRODUCT_SOURCE_PR=18'     'N1D_C3B_E2_PRODUCT_QUALIFIED_HEAD=769feb9b9f662deda2a9110e85d95bb6114ceace'     'N1D_C3B_E2_PRODUCT_QUALIFIED_TREE=cf5c232be3bc79eec4bd30ee0a90ab9247852053'     'N1D_C3B_E2_PRODUCT_MERGED_MAIN=dbbb96cc01a0e366ea56817b54028b5686cb4035'     'N1D_C3B_E2_PRODUCT_MERGED_MAIN_TREE=cf5c232be3bc79eec4bd30ee0a90ab9247852053'     'N1D_C3B_E2_PRODUCT_TREE_EQUIVALENCE=PASS'     'N1D_C3B_E2_RECONCILED_CANONICAL_COLLISION_COUNT=1'     'N1D_C3B_E2_PHOSPHOR_PROVENANCE_PATH=third_party/phosphor-icons/PROVENANCE.md'     'N1D_C3B_E2_PHOSPHOR_PROVENANCE_OLD_CANONICAL_BLOB=89827af57b4b8b7f7fe02a82df5907d72a3db751'     'N1D_C3B_E2_PHOSPHOR_PROVENANCE_QUALIFIED_PRODUCT_BLOB=b0ee56440b8db5c130321ae83e259f097832ad8c'     'N1D_C3B_E2_PHOSPHOR_PROVENANCE_CANONICAL_BLOB=b0ee56440b8db5c130321ae83e259f097832ad8c'     'N1D_C3B_E2_PHOSPHOR_PROVENANCE_RECONCILIATION=PASS_BYTE_IDENTICAL_QUALIFIED_PRODUCT_SOURCE'     'N1D_C3B_E2_CANONICAL_IGNORE_EXCEPTION_COUNT=2'     'N1D_C3B_E2_CANONICAL_IGNORE_EXCEPTION_1=third_party/pinyin_zh/inputs/Unihan.zip'     'N1D_C3B_E2_CANONICAL_IGNORE_EXCEPTION_1_GIT_BLOB=03e93bfb1f674a2cdd811e5f88c17c5a5402f3c5'     'N1D_C3B_E2_CANONICAL_IGNORE_EXCEPTION_1_SHA256=4c93ea9c1f636451729a840978f1667a53886af37ba854fdcce109721c63d43e'     'N1D_C3B_E2_CANONICAL_IGNORE_EXCEPTION_2=third_party/pinyin_zh/inputs/cedict_1_0_ts_utf-8_mdbg.zip'     'N1D_C3B_E2_CANONICAL_IGNORE_EXCEPTION_2_GIT_BLOB=b5530bc5f1b343a98c7d839cad67284f5881736b'     'N1D_C3B_E2_CANONICAL_IGNORE_EXCEPTION_2_SHA256=5a5ea3da98372bfba8f751b82f4fab62911dfb4c43d65b01ea95146e69b35d87'     'N1D_C3B_E2_CANONICAL_IGNORE_EXCEPTION_POLICY=QUALIFIED_TRACKED_PROVENANCE_INPUTS_ONLY'     'N1D_C3B_E2_CRLF_BATCH_FILE_COUNT=1'     'N1D_C3B_E2_CRLF_BATCH_FILE_1=apps/titan2/platform/gradlew.bat'     'N1D_C3B_E2_CRLF_BATCH_FILE_1_GIT_BLOB=5eed7ee8452842305a18a4eb967442683808226a'     'N1D_C3B_E2_CRLF_BATCH_POLICY=PRESERVE_QUALIFIED_WINDOWS_WRAPPER_BYTES_ONLY'     'N1D_C3B_E2_BINARY_LINE_ENDING_POLICY=SKIP_GIT_CLASSIFIED_BINARY_STAGED_PATHS'     'N1D_C3B_E2_PRODUCT_MODULE_COUNT=5'     'N1D_C3B_E2_PRODUCT_MODULES=SableTitan2Keyboard,SableTitan2Camera,SableTitan2DisplayCompat,SableTitan2Setup,SableTitan2RadioDiag'     'N1D_C3B_E2_PROTOTYPE_ADMISSION_ALLOWED=NO'     'N1D_C3B_E2_STANDALONE_HOME_ADMISSION_ALLOWED=NO'     'N1D_C3B_E2_REFERENCE_SOURCE_RUNTIME_ADMISSION_ALLOWED=NO'     'N1D_C3B_E2_PRESIGNED_PRODUCT_APK_ADMISSION_ALLOWED=NO'     'N1D_C3B_E2_STAGING_ADAPTER=build/titan2/stage-c3b-product-review.sh'     'N1D_C3B_E2_STAGING_CONTRACT=build/gates/n1d-c3b-product-review-staging-contract.sh'     'N1D_C3B_E2_SOURCE_ADMISSION_STATUS=PENDING_CANONICAL_STAGING_REVIEW'     'N1D_C3B_E2_PRODUCT_IDENTITY_STATUS=PENDING_CANONICAL_PRODUCT_COMPOSITION'     'N1D_C3B_E2_TARGET_FILES_AUTHORIZED=NO'     'N1D_C3B_E2_OTA_AUTHORIZED=NO'     'N1D_C3B_E2_DEVICE_CONTACT_AUTHORIZED=NO'     'N1D_C3B_E2_FLASH_AUTHORIZED=NO'     'N1D_C3B_E2_SIGNING_AUTHORIZED=NO'     'N1D_C3B_E2_PHYSICAL_RUNTIME_AUTHORIZED=NO'     'N1D_C3B_E2_RELEASE_ELIGIBLE=NO'
do
    require_line "$line"
done

# shellcheck source=/dev/null
source "$PROFILE"

[[ "$N1D_C3B_E2_PRODUCT_QUALIFIED_TREE" == "$N1D_C3B_E2_PRODUCT_MERGED_MAIN_TREE" ]] ||
    fail "qualified_and_main_tree_mismatch"

PHOSPHOR_PROVENANCE="$ROOT/$N1D_C3B_E2_PHOSPHOR_PROVENANCE_PATH"
[[ -f "$PHOSPHOR_PROVENANCE" ]] || fail "missing_phosphor_provenance=$PHOSPHOR_PROVENANCE"
phosphor_blob="$(git -C "$ROOT" hash-object "$PHOSPHOR_PROVENANCE")"
[[ "$phosphor_blob" == "$N1D_C3B_E2_PHOSPHOR_PROVENANCE_CANONICAL_BLOB" ]] ||
    fail "phosphor_provenance_blob expected=$N1D_C3B_E2_PHOSPHOR_PROVENANCE_CANONICAL_BLOB actual=$phosphor_blob"
[[ "$N1D_C3B_E2_PHOSPHOR_PROVENANCE_CANONICAL_BLOB" == "$N1D_C3B_E2_PHOSPHOR_PROVENANCE_QUALIFIED_PRODUCT_BLOB" ]] ||
    fail "phosphor_provenance_not_byte_identical_to_qualified_product_source"

for ignored_rel in     "$N1D_C3B_E2_CANONICAL_IGNORE_EXCEPTION_1"     "$N1D_C3B_E2_CANONICAL_IGNORE_EXCEPTION_2"
do
    [[ "$ignored_rel" == third_party/pinyin_zh/inputs/*.zip ]] ||
        fail "ignored_input_outside_pinyin_provenance_scope=$ignored_rel"
done

[[ "$N1D_C3B_E2_CRLF_BATCH_FILE_1" == "apps/titan2/platform/gradlew.bat" ]] ||
    fail "unexpected_crlf_batch_path=$N1D_C3B_E2_CRLF_BATCH_FILE_1"
[[ "$N1D_C3B_E2_CRLF_BATCH_FILE_1" == *.bat ]] ||
    fail "crlf_exception_not_batch_file=$N1D_C3B_E2_CRLF_BATCH_FILE_1"

grep -Fxq 'N1D_C3B_PRODUCT_IDENTITY_STATUS=ENGINEERING_GENERATED_TREBLEDROID_PENDING_E2' "$TRANSITION" ||
    fail "e1_transition_no_longer_hands_product_identity_to_e2"
grep -Fxq 'N1D_C3B_SABLE_PRODUCT_ADMISSION_OWNER=E2_CANONICAL_ENGINEERING_LANE' "$TRANSITION" ||
    fail "e2_admission_owner_missing"

grep -Fq 'n1d-c3b-e2-product-admission.env' "$ADAPTER" ||
    fail "adapter_not_bound_to_e2_profile"
grep -Fq 'N1D_C3B_E2_PRODUCT_QUALIFIED_HEAD' "$ADAPTER" ||
    fail "adapter_missing_qualified_head_binding"
grep -Fq 'N1D_C3B_E2_PRODUCT_QUALIFIED_TREE' "$ADAPTER" ||
    fail "adapter_missing_qualified_tree_binding"
grep -Fq 'C3B_PRODUCT_STAGE_TREE=PASS' "$ADAPTER" ||
    fail "adapter_missing_tree_pass_marker"

if grep -Eq 'N1D_C3B_E2_(TARGET_FILES|OTA|DEVICE_CONTACT|FLASH|SIGNING|PHYSICAL_RUNTIME|RELEASE_ELIGIBLE)_(AUTHORIZED|ELIGIBLE)=YES' "$PROFILE"; then
    fail "forbidden_e2_authorization"
fi

echo "N1D_C3B_E2_E1_PREREQUISITE=PASS_SYSTEMIMAGE"
echo "N1D_C3B_E2_PRODUCT_SOURCE_BINDING=PASS_EXACT_QUALIFIED_HEAD_AND_TREE"
echo "N1D_C3B_E2_PRODUCT_TREE_EQUIVALENCE=PASS"
echo "N1D_C3B_E2_CANONICAL_COLLISION_RECONCILIATION=PASS_PHOSPHOR_PROVENANCE_BYTE_IDENTICAL"
echo "N1D_C3B_E2_CANONICAL_IGNORE_EXCEPTION_POLICY=PASS_2_QUALIFIED_PINYIN_PROVENANCE_ARCHIVES"
echo "N1D_C3B_E2_LINE_ENDING_POLICY=PASS_1_QUALIFIED_CRLF_BATCH_WRAPPER"
echo "N1D_C3B_E2_BINARY_LINE_ENDING_POLICY=PASS_GIT_CLASSIFIED_BINARIES_EXCLUDED"
echo "N1D_C3B_E2_PRODUCT_MODULE_SCOPE=PASS_5_SOURCE_CANDIDATES"
echo "N1D_C3B_E2_PROTOTYPE_POLICY=PASS_EXCLUDED"
echo "N1D_C3B_E2_RUNTIME_AUTHORITY=PASS_BLOCKED"
echo "N1D_C3B_E2_RELEASE_AUTHORITY=PASS_BLOCKED"
echo "N1D_C3B_E2_PRODUCT_ADMISSION_CONTRACT=PASS"
